#!/usr/bin/env bash
# render-workflows.sh — Render .github/workflows/claude*.yml from detected project context.
#
# Reads detection from scripts/detect-project.sh, writes two YAML files:
#   .github/workflows/claude-code-review.yml
#   .github/workflows/claude.yml
#
# The output files carry an "Auto-generated by scripts/render-workflows.sh" header.
# Re-running the script will overwrite files with that header but will SKIP files
# that have been manually edited (header removed).
#
# Usage:
#   bash scripts/render-workflows.sh                # render to .github/workflows/
#   bash scripts/render-workflows.sh --out <dir>    # render to a different dir
#   bash scripts/render-workflows.sh --dry-run      # print to stdout, no writes
#   bash scripts/render-workflows.sh --force        # overwrite even manual edits
#   bash scripts/render-workflows.sh --show-vars    # print detected vars and exit

set -euo pipefail

OUT_DIR=".github/workflows"
PROVIDER="claude"     # claude | codex | both
INCLUDE_CI=0          # 1 = also generate ci.yml
DRY=0
FORCE=0
SHOW_VARS=0

while [[ $# -gt 0 ]]; do
  case "$1" in
    --out) OUT_DIR="$2"; shift 2 ;;
    --provider) PROVIDER="$2"; shift 2 ;;
    --include-ci) INCLUDE_CI=1; shift ;;
    --dry-run) DRY=1; shift ;;
    --force) FORCE=1; shift ;;
    --show-vars) SHOW_VARS=1; shift ;;
    -h|--help) sed -n '2,/^$/p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
    *) echo "Unknown: $1" >&2; exit 1 ;;
  esac
done

case "$PROVIDER" in
  claude|codex|both) ;;
  *) echo "--provider must be one of: claude, codex, both (got: $PROVIDER)" >&2; exit 1 ;;
esac

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

say() { printf "\033[1;36m▸\033[0m %s\n" "$*" >&2; }
ok()  { printf "\033[1;32m✓\033[0m %s\n" "$*" >&2; }
warn(){ printf "\033[1;33m⚠\033[0m %s\n" "$*" >&2; }
err() { printf "\033[1;31m✗\033[0m %s\n" "$*" >&2; exit 1; }

# ---- Source detector output ----
[[ -x "$SCRIPT_DIR/detect-project.sh" ]] || err "Missing $SCRIPT_DIR/detect-project.sh"

eval "$(bash "$SCRIPT_DIR/detect-project.sh" --quiet)"

if (( SHOW_VARS == 1 )); then
  _join() { local IFS=" "; echo "${1:-<none>}"; }
  cat <<EOF
Detected project context:
  PROJECT_TYPE     = $PROJECT_TYPE
  BASE_BRANCH      = $BASE_BRANCH
  IS_MONOREPO      = $IS_MONOREPO
  REPO_SIZE        = $REPO_SIZE ($REPO_FILE_COUNT files)
  PACKAGE_MANAGER  = ${PACKAGE_MANAGER:-<none>}
  TEST_COMMAND     = ${TEST_COMMAND:-<none>}
  LINT_COMMAND     = ${LINT_COMMAND:-<none>}
  TYPECHECK        = ${TYPECHECK_COMMAND:-<none>}
  REVIEW_MODEL     = $REVIEW_MODEL
  REVIEW_MAX_TURNS = $REVIEW_MAX_TURNS
  CLAUDE_MAX_TURNS = $CLAUDE_MAX_TURNS
  PATHS_IGNORE     = ${PATHS_IGNORE[*]:-<none>}
  STYLE_FILES      = ${STYLE_FILES[*]:-<none>}
  DANGER_PATHS     = ${DANGER_PATHS[*]:-<none>}
  SUPERSET         = $SUPERSET_DETECTED
EOF
  exit 0
fi

# ---- Block builders (all use safe array expansion for nounset) ----
build_paths_ignore() {
  local p
  for p in ${PATHS_IGNORE[@]+"${PATHS_IGNORE[@]}"}; do
    printf '      - "%s"\n' "$p"
  done
}

build_style_guide_lines() {
  if (( ${#STYLE_FILES[@]} == 0 )); then
    echo "            (No project style guide detected — apply general best practices.)"
    return
  fi
  local f
  for f in "${STYLE_FILES[@]}"; do
    echo "            - $f (read top of file before flagging style issues)"
  done
}

build_review_priorities() {
  cat <<EOF
            - Correctness: logic bugs, edge cases, error handling, race conditions
            - Security: input validation at boundaries, auth, secrets, injection
            - Maintainability: naming, single-responsibility, dead code, duplication
EOF

  if [[ -n "$TEST_COMMAND" ]]; then
    echo "            - Tests: new behavior should have a test (project uses: \`$TEST_COMMAND\`)"
  fi
  if [[ -n "$TYPECHECK_COMMAND" ]]; then
    echo "            - Types: PR should pass \`$TYPECHECK_COMMAND\`"
  fi
  if (( ${#DANGER_PATHS[@]} > 0 )); then
    echo "            - Sensitive paths flagged for extra scrutiny:"
    local p
    for p in "${DANGER_PATHS[@]}"; do
      echo "              - $p"
    done
  fi
  if [[ "$IS_MONOREPO" == "1" ]]; then
    echo "            - Monorepo: shared/lib changes must typecheck downstream consumers"
  fi
  case "$PROJECT_TYPE" in
    *node*)   echo "            - Node specifics: avoid \`any\`, prefer Result/Either over thrown strings, lock-file changes need explanation" ;;
    *python*) echo "            - Python specifics: type hints on public APIs, avoid bare except, no implicit IO in pure modules" ;;
    *go*)     echo "            - Go specifics: errors wrapped (%w), context-aware funcs, no goroutine leaks" ;;
    *rust*)   echo "            - Rust specifics: explicit lifetimes preferred, avoid \`unwrap()\` in lib code, clippy must pass" ;;
  esac
}

build_disallowed_tools() {
  # base list always present
  local items=('Bash(git push --force *)' 'Bash(rm -rf *)' 'Bash(sudo *)')
  # add Edit() blockers for sensitive paths
  local p
  for p in ${DANGER_PATHS[@]+"${DANGER_PATHS[@]}"}; do
    items+=("Edit($p)")
  done
  # comma-join
  local IFS=,
  echo "${items[*]}"
}

# ---- YAML builders ----
build_review_yml() {
  cat <<EOF
# Auto-generated by scripts/render-workflows.sh.
# To re-render after repo structure changes:    bash scripts/render-workflows.sh
# To take manual control:                       delete this header line and edit freely
#                                               (the renderer skips files without this header).
#
# Detected project context at render time:
#   Type            : $PROJECT_TYPE
#   Base branch     : $BASE_BRANCH
#   Monorepo        : $IS_MONOREPO
#   Repo size       : $REPO_SIZE ($REPO_FILE_COUNT files)
#   Package manager : ${PACKAGE_MANAGER:-<none>}
#   Test            : ${TEST_COMMAND:-<none>}
#   Lint            : ${LINT_COMMAND:-<none>}
#   Typecheck       : ${TYPECHECK_COMMAND:-<none>}
#   Style guides    : ${STYLE_FILES[*]:-<none>}
#   Sensitive paths : ${#DANGER_PATHS[@]} entries

name: Claude Code Review

on:
  pull_request:
    types: [opened, synchronize, reopened, ready_for_review]
    paths-ignore:
$(build_paths_ignore)

concurrency:
  group: claude-review-\${{ github.event.pull_request.number }}
  cancel-in-progress: true

jobs:
  review:
    runs-on: ubuntu-latest
    timeout-minutes: 10
    permissions:
      contents: read
      pull-requests: write
      issues: read
      id-token: write       # OIDC

    steps:
      - uses: actions/checkout@v6
        with:
          fetch-depth: 1

      - uses: anthropics/claude-code-action@v1
        with:
          claude_code_oauth_token: \${{ secrets.CLAUDE_CODE_OAUTH_TOKEN }}
          plugin_marketplaces: 'https://github.com/anthropics/claude-code.git'
          plugins: 'code-review@claude-code-plugins'
          prompt: |
            /code-review:code-review \${{ github.repository }}/pull/\${{ github.event.pull_request.number }}

            # Project-specific review context (baked in at workflow render time from this repo's actual layout)
            Repo summary: ${REPO_DESCRIPTION}
            Project type: $PROJECT_TYPE ($REPO_SIZE, $REPO_FILE_COUNT tracked files)$([[ "$IS_MONOREPO" == "1" ]] && echo " — monorepo")
            Top-level source dirs: ${TOP_DIRS[*]:-(none)}
            Entry points: ${ENTRY_FILES[*]:-(none auto-detected; reviewer should scan top-level files)}
            Test command: ${TEST_COMMAND:-(none — flag missing tests as Major)}
            Typecheck command: ${TYPECHECK_COMMAND:-(none)}
            Lint command: ${LINT_COMMAND:-(none)}
            Style guides at repo root: ${STYLE_FILES[*]:-(none — apply general best practices)}
            Sensitive paths (require explicit rationale on touch):
$([[ ${#DANGER_PATHS[@]} -gt 0 ]] && printf '              - %s\n' "${DANGER_PATHS[@]}" || echo "              (none configured)")
            Review priorities (in order, applied to THIS repo's structure):
$(build_review_priorities)

            Senior reviewer discipline (apply throughout, not just on a first pass):
            - Architecture fit: does the change live in the right layer / module? Does it follow existing patterns or contradict them silently? Flag silent precedent breaks.
            - Scope discipline: is this PR doing ONE thing, or sneaking in unrelated refactors? Call out scope creep — request a split if structural changes ride along with the stated fix.
            - Test quality (not just presence): do tests assert BEHAVIOR (inputs → outputs / side effects) or implementation (mocks of internals)? Are boundary, error, empty, and concurrent cases covered? Are tests deterministic — no time / order / network dependencies?
            - Failure modes: what happens when network / DB / external dep fails? Are retries idempotent + bounded? Timeouts set? Is degradation graceful, or does one failure cascade?
            - Concurrency hazards: shared state, race conditions, transaction isolation, async deadlock paths, async cancellation safety. Flag any new shared mutable state without a clear owner.
            - API contracts: any breaking change to public APIs, types, wire formats, CLI flags, env vars, or stored data shapes? Is there a migration story (and a rollback)?
            - Performance regressions: O(N²) loops added, N+1 queries, allocations in hot paths, cache invalidation correctness. Spot-check loops over external collections.
            - Observability gap: are new code paths logged / metered / traceable so a future on-call can debug from prod data alone? Errors without context are not loggable.
            - Security beyond input validation: secrets in logs / error messages, authorization checked at every boundary (NOT just authentication), PII handling, TOCTOU windows, SSRF on outbound requests.
            - Root cause vs symptom: does this fix the root cause, or paper over a symptom that will recur elsewhere? If the fix is local but the bug class is general, flag it.

            Reading order (use it — don't review top-to-bottom by file):
            - Skim the diff for SHAPE first: which files, which layers. Flag if shape sprawls beyond the PR title's promise.
            - Read tests BEFORE implementation — tests are the spec.
            - Read implementation last; verify it matches the test's intent.
            - Pause and zoom on every line that touches: auth, money, time / dates, external IO, regex, concurrency primitives, migrations.
            - If the diff is "remove and rewrite", \`git blame\` the deleted block to see what edge cases were addressed historically. The new version must cover them.

            Self-check before posting comments:
            - "If the author left tomorrow, could a new dev maintain this?" — if no, that's a Major.
            - "What is the worst case if this fails in prod at 3am?" — if you can't answer, request observability or a guardrail.
            - "Have I considered the inverse case?" (empty input, max input, hostile input, already-applied state)
            - "Is this comment actionable as-is, or vague?" If vague, rewrite with file:line + the specific change you want.

            Output rules:
            - Cite file:line for every issue. Anchor on entry points and top-level dirs above when applicable.
            - Group findings by severity: Reject (blocks merge) / Major / Minor / Nit.
            - Skip trivial nits if the PR is large; lead with structural concerns that align or conflict with the repo summary above.
            - Be concise. No preamble. No "great work!" filler. State the issue, the impact, the suggested change.
          claude_args: |
            --max-turns $REVIEW_MAX_TURNS
            --model $REVIEW_MODEL
          use_sticky_comment: true
EOF
}

build_claude_yml() {
  local disallowed
  disallowed=$(build_disallowed_tools)

  cat <<EOF
# Auto-generated by scripts/render-workflows.sh.
# To re-render: bash scripts/render-workflows.sh
# To take manual control: delete this header line and edit freely.
#
# Detected project context:
#   Type            : $PROJECT_TYPE
#   Base branch     : $BASE_BRANCH
#   Monorepo        : $IS_MONOREPO
#   Repo size       : $REPO_SIZE
#   Sensitive paths : ${DANGER_PATHS[*]:-<none>}

name: Claude Code

on:
  issue_comment:
    types: [created]
  pull_request_review_comment:
    types: [created]
  pull_request_review:
    types: [submitted]
  issues:
    types: [opened, assigned]

concurrency:
  group: claude-\${{ github.event.issue.number || github.run_id }}
  cancel-in-progress: true

jobs:
  claude:
    if: |
      (github.event_name == 'issue_comment' && contains(github.event.comment.body, '@claude')) ||
      (github.event_name == 'pull_request_review_comment' && contains(github.event.comment.body, '@claude')) ||
      (github.event_name == 'pull_request_review' && contains(github.event.review.body, '@claude')) ||
      (github.event_name == 'issues' && (contains(github.event.issue.body, '@claude') || contains(github.event.issue.title, '@claude')))
    runs-on: ubuntu-latest
    timeout-minutes: 15
    permissions:
      contents: write       # @claude can commit fixes
      pull-requests: write
      issues: write
      actions: read
      id-token: write       # OIDC

    steps:
      - uses: actions/checkout@v6
        with:
          fetch-depth: 0    # full history for blame/log

      - uses: anthropics/claude-code-action@v1
        with:
          claude_code_oauth_token: \${{ secrets.CLAUDE_CODE_OAUTH_TOKEN }}
          additional_permissions: |
            actions: read
          claude_args: |
            --max-turns $CLAUDE_MAX_TURNS
            --model $REVIEW_MODEL
            --disallowed-tools "$disallowed"
EOF
}

build_ci_yml() {
  # Render a basic CI workflow tailored to detected project type.
  local setup_block install_cmd lint_cmd typecheck_cmd test_cmd

  case "$PROJECT_TYPE" in
    *node*)
      local pm="${PACKAGE_MANAGER:-npm}"
      setup_block=$(cat <<SETUP
      - uses: actions/setup-node@v4
        with:
          node-version: '20'
          cache: '$pm'
SETUP
)
      [[ "$pm" == "pnpm" ]] && setup_block="${setup_block}
      - uses: pnpm/action-setup@v3
        with:
          version: 9"
      install_cmd="$pm install --frozen-lockfile 2>/dev/null || $pm install"
      ;;
    *python*)
      setup_block=$(cat <<'SETUP'
      - uses: actions/setup-python@v5
        with:
          python-version: '3.11'
          cache: 'pip'
SETUP
)
      install_cmd="pip install -e .[dev] 2>/dev/null || pip install -r requirements.txt"
      ;;
    *go*)
      setup_block=$(cat <<'SETUP'
      - uses: actions/setup-go@v5
        with:
          go-version: '1.22'
SETUP
)
      install_cmd="go mod download"
      ;;
    *rust*)
      setup_block=$(cat <<'SETUP'
      - uses: actions-rust-lang/setup-rust-toolchain@v1
SETUP
)
      install_cmd="cargo fetch"
      ;;
    *)
      setup_block="      # No matching setup detected"
      install_cmd="echo 'No install step detected'"
      ;;
  esac

  lint_cmd="${LINT_COMMAND:-echo lint not detected; skipping}"
  typecheck_cmd="${TYPECHECK_COMMAND:-echo typecheck not detected; skipping}"
  test_cmd="${TEST_COMMAND:-echo test not detected; skipping}"

  cat <<EOF
# Auto-generated by scripts/render-workflows.sh.
# Generic CI for $PROJECT_TYPE. Edit freely; the renderer only overwrites
# files with the auto-generated header.
#
# Detected commands:
#   install:   $install_cmd
#   lint:      $lint_cmd
#   typecheck: $typecheck_cmd
#   test:      $test_cmd

name: CI

on:
  pull_request:
    types: [opened, synchronize, reopened, ready_for_review]
  push:
    branches: [$BASE_BRANCH]

concurrency:
  group: ci-\${{ github.ref }}
  cancel-in-progress: true

jobs:
  test:
    runs-on: ubuntu-latest
    timeout-minutes: 15
    steps:
      - uses: actions/checkout@v6

$setup_block

      - run: $install_cmd

      - run: $lint_cmd
        continue-on-error: false

      - run: $typecheck_cmd
        continue-on-error: false

      - run: $test_cmd
EOF
}

build_codex_review_yml() {
  cat <<EOF
# Auto-generated by scripts/render-workflows.sh.
# Codex Actions review workflow. Prompt is INLINE — baked in at render time
# from this repo's actual layout, mirroring claude-code-review.yml. Re-render
# (\`bash scripts/render-workflows.sh --force\`) after structure changes.
#
# Action: https://github.com/openai/codex-action

name: Codex Review

on:
  pull_request:
    types: [opened, synchronize, reopened, ready_for_review]
    paths-ignore:
$(build_paths_ignore)

concurrency:
  group: codex-review-\${{ github.event.pull_request.number }}
  cancel-in-progress: true

jobs:
  review:
    runs-on: ubuntu-latest
    timeout-minutes: 10
    permissions:
      contents: read
      pull-requests: write
      issues: read
      id-token: write

    steps:
      - uses: actions/checkout@v6
        with:
          fetch-depth: 1
          ref: refs/pull/\${{ github.event.pull_request.number }}/merge

      - name: Pre-fetch base + head refs
        env:
          PR_BASE_REF: \${{ github.event.pull_request.base.ref }}
          PR_NUMBER: \${{ github.event.pull_request.number }}
        run: |
          git fetch --no-tags origin "\$PR_BASE_REF" "+refs/pull/\$PR_NUMBER/head"

      - name: Run Codex review
        id: run_codex
        uses: openai/codex-action@v1.8
        with:
          openai-api-key: \${{ secrets.OPENAI_API_KEY }}
          prompt: |
            Review PR \${{ github.repository }}/pull/\${{ github.event.pull_request.number }}.

            # Project-specific context (baked in at workflow render time from this repo's actual layout)
            Repo summary: ${REPO_DESCRIPTION}
            Project type: $PROJECT_TYPE ($REPO_SIZE, $REPO_FILE_COUNT tracked files)$([[ "$IS_MONOREPO" == "1" ]] && echo " — monorepo")
            Top-level source dirs: ${TOP_DIRS[*]:-(none)}
            Entry points: ${ENTRY_FILES[*]:-(none auto-detected; scan top-level files)}
            Test command: ${TEST_COMMAND:-(none — flag missing tests as Major)}
            Typecheck command: ${TYPECHECK_COMMAND:-(none)}
            Lint command: ${LINT_COMMAND:-(none)}
            Style guides at repo root: ${STYLE_FILES[*]:-(none — apply general best practices)}
            Sensitive paths (require explicit rationale on touch):
$([[ ${#DANGER_PATHS[@]} -gt 0 ]] && printf '              - %s\n' "${DANGER_PATHS[@]}" || echo "              (none configured)")
            Review priorities (in order, applied to THIS repo's structure):
$(build_review_priorities)

            Senior reviewer discipline:
            - Architecture fit: change in right layer / module? Follows existing patterns or contradicts silently?
            - Scope discipline: PR doing ONE thing? Flag scope creep.
            - Test quality: behavior vs implementation? Boundary / error / empty / concurrent cases? Deterministic?
            - Failure modes: network / DB / external fail → retries idempotent + bounded? Timeouts? Graceful degradation?
            - Concurrency: shared mutable state, race conditions, transaction isolation, async cancellation.
            - API contracts: breaking changes to public APIs / wire formats / stored data? Migration + rollback?
            - Performance: O(N²), N+1 queries, hot-path allocations, cache invalidation.
            - Observability: new paths logged / metered for prod debugging?
            - Security beyond input validation: secrets in logs, authorization at every boundary, PII, TOCTOU.
            - Root cause vs symptom: does it fix the underlying issue or paper over it?

            Reading order: skim diff for shape → read tests (the spec) → read implementation → zoom on auth / money / time / IO / regex / concurrency / migrations.

            Self-check before posting: actionable as-is? worst-case-at-3am answerable? inverse case considered?

            Output rules:
            - Cite file:line for every issue. Anchor on entry points and top-level dirs above.
            - Group findings by severity: Reject (blocks merge) / Major / Minor / Nit.
            - Skip trivial nits if the PR is large; lead with structural concerns.
            - Be concise. No preamble. State issue + impact + suggested change.

      - name: Post review as PR comment
        if: \${{ steps.run_codex.outputs.final-message != '' }}
        env:
          PR_NUMBER: \${{ github.event.pull_request.number }}
          BODY: \${{ steps.run_codex.outputs.final-message }}
          GH_TOKEN: \${{ github.token }}
        run: |
          gh pr comment "\$PR_NUMBER" --body "\$BODY"
EOF
}

# NOTE: build_review_prompt_md() was removed. Review prompts are now INLINE
# in the workflow YAMLs (claude-code-review.yml + codex-review.yml), baked
# in at render time from this repo's actual structure (TOP_DIRS, ENTRY_FILES,
# REPO_DESCRIPTION, DANGER_PATHS). Edit the YAML directly to tune review
# behavior, then commit + push. No more cat-from-file indirection.

# ---- Write or dump ----
HEADER_MARK="Auto-generated by scripts/render-workflows.sh"

write_or_dump() {
  local content="$1" target="$2"

  if (( DRY == 1 )); then
    printf '\n=== %s ===\n%s\n' "$target" "$content"
    return
  fi

  if [[ -f "$target" ]]; then
    # Search the first 10 lines for the auto-gen header. Strip CR (Windows
    # CRLF) and BOM (UTF-8 byte-order mark) before comparison so files edited
    # on Windows or saved with BOM still match correctly.
    if head -10 "$target" | tr -d '\r' | sed '1s/^\xef\xbb\xbf//' | grep -qF "$HEADER_MARK"; then
      printf '%s\n' "$content" > "$target"
      ok "Re-rendered $target"
    elif (( FORCE == 1 )); then
      printf '%s\n' "$content" > "$target"
      ok "Force-overwrote $target"
    else
      warn "$target exists and is NOT auto-generated; skipping (use --force to overwrite)"
    fi
  else
    mkdir -p "$(dirname "$target")"
    printf '%s\n' "$content" > "$target"
    ok "Wrote $target"
  fi
}

PROJECT_DIR="${CLAUDE_PROJECT_DIR:-$(pwd)}"

# ---- Render workflow YAMLs based on provider + include-ci ----
GENERATED_FILES=()

if (( INCLUDE_CI == 1 )); then
  write_or_dump "$(build_ci_yml)" "$OUT_DIR/ci.yml"
  GENERATED_FILES+=("$OUT_DIR/ci.yml")
fi

if [[ "$PROVIDER" == "claude" || "$PROVIDER" == "both" ]]; then
  write_or_dump "$(build_review_yml)" "$OUT_DIR/claude-code-review.yml"
  write_or_dump "$(build_claude_yml)" "$OUT_DIR/claude.yml"
  GENERATED_FILES+=("$OUT_DIR/claude-code-review.yml" "$OUT_DIR/claude.yml")
fi

if [[ "$PROVIDER" == "codex" || "$PROVIDER" == "both" ]]; then
  write_or_dump "$(build_codex_review_yml)" "$OUT_DIR/codex-review.yml"
  GENERATED_FILES+=("$OUT_DIR/codex-review.yml")
fi

if (( DRY == 0 )); then
  echo "" >&2
  say "Done. Files placed in $OUT_DIR/ (provider=$PROVIDER, include-ci=$INCLUDE_CI)"
  say "Generated: ${GENERATED_FILES[*]}"
  say "Next: review them, then commit + push:"
  echo "    git add ${GENERATED_FILES[*]}" >&2
  echo "    git commit -m 'Add 24hour-ClaudeCode workflows'" >&2
  echo "    git push" >&2
fi
